//! Port of `src/parser/seclang-scanner.ll` (the flex scanner of the SecLang
//! configuration language).
//!
//! The C++ scanner is generated by flex. This port keeps the flex
//! specification itself: the named definitions ([`DEFS`]) and the rules
//! ([`RULES`], each one with its start conditions, its pattern written in the
//! flex regular expression syntax, and its action expressed as a short list
//! of [`Op`]s) are transcribed verbatim from the `.ll` file, and a small
//! engine reproduces the flex matching semantics:
//!
//! * the patterns are compiled (once per process) into an NFA, which is
//!   determinised lazily (subset construction, cached);
//! * at each step the rules active in the current start condition are tried
//!   together and the longest match wins, ties going to the rule that comes
//!   first in the specification;
//! * flex's implicit default rule (`.|\n` with `ECHO`) is the last rule of
//!   every start condition: unmatched bytes are copied to stdout;
//! * `YY_USER_ACTION` advances the location by the length of the match
//!   before the action runs, `yyless(n)` gives back all but `n` bytes;
//! * `<<EOF>>` pops the buffer stack (`Include`, `SecRemoteRules`) and
//!   returns the end token once the main buffer is exhausted.
//!
//! The scanner works on bytes, as flex does: configuration files are not
//! required to be UTF-8.

use std::collections::HashMap;
use std::io::Write;
use std::sync::{Mutex, OnceLock};

use crate::parser::driver::Driver;
use crate::parser::seclang_parser::{Location, sym};
use crate::rules_set_properties::OnFailedRemoteRulesAction;
use crate::utils::https_client::HttpsClient;
use crate::utils::string::{parser_sanitizer, split};
use crate::utils::system::{expand_env, find_resource};

/// A token handed to the parser (`yy::seclang_parser::symbol_type`).
#[derive(Debug)]
pub(crate) struct Token {
    /// Symbol kind (one of the [`sym`] constants).
    pub kind: u16,
    /// Semantic value (`std::string` in C++); empty for the tokens without
    /// a value.
    pub value: Vec<u8>,
    pub loc: Location,
}

/// `throw p::syntax_error(*driver.loc.back(), "")` from a scanner action:
/// the error was already reported through `Driver::error`.
#[derive(Debug)]
pub(crate) struct ScanError {
    pub loc: Location,
}

/// The flex start conditions (`%x`). `Initial` is flex's `INITIAL`.
/// (`SETVAR_ACTION_NONQUOTED_WAITING_COLLECTION_ELEM` and
/// `SETVAR_ACTION_QUOTED_WAITING_COLLECTION_ELEM` are declared but never
/// entered; `BEGIN_ACTION_OPERATION` maps them to the `*_WAITING_OPERATION`
/// states.)
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Sc {
    Initial,
    ExpectingActionPredicateVariable,
    TransactionToVariable,
    ExpectingVariable,
    ExpectingOperatorEndsWithSpace,
    ExpectingOperatorEndsWithQuote,
    ExpectingActionPredicate,
    ActionPredicateEndsWithQuote,
    ActionPredicateEndsWithDoubleQuote,
    ActionPredicateEndsWithCommaOrDoubleQuote,
    Comment,
    TransitionFromOpToExpectingParameterEndsWithQuote,
    TransitionFromOpToExpectingParameterEndsWithSpace,
    ExpectingVarParameter,
    ExpectingVarParameterOrMacroNonquoted,
    ExpectingVarParameterOrMacroQuoted,
    ExpectingParameterEndsWithQuote,
    ExpectingParameterEndsWithSpace,
    ExpectingActionsEndsWithDoubleQuote,
    ExpectingActionsOnlyOne,
    TransactionFromOperatorToActions,
    TransactionFromOperatorParametersToActions,
    TransactionFromDirectiveToActions,
    NoOpInformedEndsWithSpace,
    NoOpInformedEndsWithQuote,
    FinishActions,
    LexingError,
    LexingErrorAction,
    LexingErrorVariable,
    SetvarActionNonquoted,
    SetvarActionNonquotedWaitingOperation,
    SetvarActionNonquotedWaitingContent,
    SetvarActionQuoted,
    SetvarActionQuotedWaitingOperation,
    SetvarActionQuotedWaitingContent,
}

/// Number of start conditions.
const NUM_SC: usize = Sc::SetvarActionQuotedWaitingContent as usize + 1;

/// How the semantic value of a token is computed from `yytext`.
#[derive(Debug, Clone, Copy)]
enum V {
    /// The token carries no value.
    None,
    /// `yytext`
    Text,
    /// `find_separator(yytext)`
    FindSep,
    /// `parserSanitizer(find_separator(yytext))`
    SanFindSep,
    /// `strchr(yytext, ' ') + 2`
    Strchr2,
    /// `parserSanitizer(strchr(yytext, ' ') + 2)`
    SanStrchr2,
    /// `std::string(yytext, pos, yyleng - shrink)`
    Sub(usize, usize),
}

/// Argument of `yyless`.
#[derive(Debug, Clone, Copy)]
enum L {
    /// `yyless(n)`
    Abs(usize),
    /// `yyless(yyleng - n)`
    LenMinus(usize),
}

/// One statement of a flex action.
#[derive(Debug, Clone, Copy)]
enum Op {
    /// `return p::make_<kind>(<value>, *driver.loc.back())`
    Ret(u16, V),
    /// `BEGIN(sc)`
    Begin(Sc),
    /// `BEGINX(sc)`: remembers the current start condition first.
    BeginX(Sc),
    /// `BEGINX_()`
    BeginXVarParameter,
    /// `BEGIN_PREVIOUS()`
    BeginPrevious,
    /// `BEGIN_PARAMETER()`
    BeginParameter,
    /// `BEGIN_NO_OP_INFORMED()`
    BeginNoOpInformed,
    /// `BEGIN_ACTION_OPERATION()`
    BeginActionOperation,
    /// `BEGIN_ACTION_WAITING_CONTENT()`
    BeginActionWaitingContent,
    /// `yyless(...)`
    Less(L),
    /// `driver.loc.back()->lines(1)`
    Lines,
    /// `driver.loc.back()->step()`
    Step,
    /// `state_variable_from = 1`
    SetStateVariableFrom,
    /// `if (state_variable_from == 0) { BEGIN(sc); } else { state_variable_from = 0; BEGIN(INITIAL); }`
    IfStateVariableFrom(Sc),
    /// `driver.error(*driver.loc.back(), msg, with_yytext ? yytext : ""); throw ...`
    Error(&'static str, bool),
    /// `Include` (the bool tells whether the path is quoted).
    Include(bool),
    /// `SecRemoteRules <key> <url>`
    RemoteRules,
}

/// A flex rule: the start conditions where it is active, its pattern and
/// its action.
struct LexRule {
    scs: &'static [Sc],
    pat: &'static str,
    ops: &'static [Op],
}

// ---------------------------------------------------------------------------
// Flex regular expressions
// ---------------------------------------------------------------------------

/// A set of bytes (a flex character class).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct ByteSet([u64; 4]);

impl ByteSet {
    fn insert(&mut self, b: u8) {
        self.0[(b >> 6) as usize] |= 1u64 << (b & 63);
    }

    fn contains(&self, b: u8) -> bool {
        self.0[(b >> 6) as usize] & (1u64 << (b & 63)) != 0
    }

    fn negate(&mut self) {
        for w in self.0.iter_mut() {
            *w = !*w;
        }
    }

    fn single(b: u8, case_insensitive: bool) -> Self {
        let mut s = ByteSet::default();
        s.insert(b);
        if case_insensitive {
            s.add_other_cases();
        }
        s
    }

    /// Under `(?i:...)` flex adds the other case of every letter.
    fn add_other_cases(&mut self) {
        for b in b'a'..=b'z' {
            let u = b.to_ascii_uppercase();
            if self.contains(b) || self.contains(u) {
                self.insert(b);
                self.insert(u);
            }
        }
    }

    /// `.`: anything but a newline.
    fn dot() -> Self {
        let mut s = ByteSet::default();
        s.negate();
        s.0[0] &= !(1u64 << b'\n');
        s
    }
}

/// Abstract syntax of a flex pattern.
#[derive(Debug, Clone)]
enum Re {
    Set(ByteSet),
    Cat(Vec<Re>),
    Alt(Vec<Re>),
    Star(Box<Re>),
    Plus(Box<Re>),
    Opt(Box<Re>),
    Repeat(Box<Re>, u32, Option<u32>),
}

/// Parser for the subset of the flex pattern syntax used by the SecLang
/// scanner: literals, escapes, `.`, character classes, quoted strings,
/// grouping, `(?i:...)`, alternation, `*`, `+`, `?`, `{n,m}` and `{NAME}`
/// expansions of the definitions section.
struct ReParser<'a> {
    s: &'a [u8],
    i: usize,
    case_insensitive: bool,
    defs: &'a HashMap<&'static str, &'static str>,
}

impl<'a> ReParser<'a> {
    fn parse(pattern: &'a str, case_insensitive: bool, defs: &'a HashMap<&'static str, &'static str>) -> Re {
        let mut p = ReParser { s: pattern.as_bytes(), i: 0, case_insensitive, defs };
        let re = p.parse_alt();
        assert!(p.i == p.s.len(), "trailing characters in flex pattern {:?}", pattern);
        re
    }

    fn peek(&self) -> Option<u8> {
        self.s.get(self.i).copied()
    }

    fn next(&mut self) -> u8 {
        let c = self.s[self.i];
        self.i += 1;
        c
    }

    fn parse_alt(&mut self) -> Re {
        let mut alts = vec![self.parse_cat()];
        while self.peek() == Some(b'|') {
            self.i += 1;
            alts.push(self.parse_cat());
        }
        if alts.len() == 1 { alts.pop().unwrap_or(Re::Cat(Vec::new())) } else { Re::Alt(alts) }
    }

    fn parse_cat(&mut self) -> Re {
        let mut items = Vec::new();
        while let Some(c) = self.peek() {
            if c == b'|' || c == b')' {
                break;
            }
            let atom = self.parse_atom();
            items.push(self.parse_postfix(atom));
        }
        if items.len() == 1 { items.pop().unwrap_or(Re::Cat(Vec::new())) } else { Re::Cat(items) }
    }

    fn parse_postfix(&mut self, mut atom: Re) -> Re {
        loop {
            match self.peek() {
                Some(b'*') => {
                    self.i += 1;
                    atom = Re::Star(Box::new(atom));
                }
                Some(b'+') => {
                    self.i += 1;
                    atom = Re::Plus(Box::new(atom));
                }
                Some(b'?') => {
                    self.i += 1;
                    atom = Re::Opt(Box::new(atom));
                }
                Some(b'{') if self.s.get(self.i + 1).is_some_and(|c| c.is_ascii_digit()) => {
                    self.i += 1;
                    let min = self.number();
                    let max = if self.peek() == Some(b',') {
                        self.i += 1;
                        if self.peek() == Some(b'}') { None } else { Some(self.number()) }
                    } else {
                        Some(min)
                    };
                    assert_eq!(self.next(), b'}');
                    atom = Re::Repeat(Box::new(atom), min, max);
                }
                _ => return atom,
            }
        }
    }

    fn number(&mut self) -> u32 {
        let mut n = 0u32;
        while let Some(c) = self.peek().filter(u8::is_ascii_digit) {
            n = n * 10 + u32::from(c - b'0');
            self.i += 1;
        }
        n
    }

    /// A character after a backslash.
    fn escape(&mut self) -> u8 {
        let c = self.next();
        match c {
            b'n' => b'\n',
            b't' => b'\t',
            b'r' => b'\r',
            b'f' => 0x0c,
            b'v' => 0x0b,
            b'a' => 0x07,
            b'b' => 0x08,
            b'0'..=b'7' => {
                let mut v = u32::from(c - b'0');
                for _ in 0..2 {
                    match self.peek() {
                        Some(d @ b'0'..=b'7') => {
                            v = v * 8 + u32::from(d - b'0');
                            self.i += 1;
                        }
                        _ => break,
                    }
                }
                v as u8
            }
            b'x' => {
                let mut v = 0u32;
                for _ in 0..2 {
                    match self.peek().and_then(|d| (d as char).to_digit(16)) {
                        Some(d) => {
                            v = v * 16 + d;
                            self.i += 1;
                        }
                        None => break,
                    }
                }
                v as u8
            }
            _ => c,
        }
    }

    fn parse_atom(&mut self) -> Re {
        let c = self.next();
        match c {
            b'(' => {
                let saved = self.case_insensitive;
                if self.peek() == Some(b'?') {
                    // (?i: ...) / (?-i: ...)
                    self.i += 1;
                    let mut on = true;
                    loop {
                        match self.next() {
                            b':' => break,
                            b'-' => on = false,
                            b'i' => self.case_insensitive = on,
                            _ => {}
                        }
                    }
                }
                let inner = self.parse_alt();
                assert_eq!(self.next(), b')', "unbalanced parenthesis in flex pattern");
                self.case_insensitive = saved;
                inner
            }
            b'[' => self.parse_class(),
            b'"' => {
                let mut items = Vec::new();
                loop {
                    let c = self.next();
                    if c == b'"' {
                        break;
                    }
                    let c = if c == b'\\' { self.escape() } else { c };
                    items.push(Re::Set(ByteSet::single(c, self.case_insensitive)));
                }
                Re::Cat(items)
            }
            b'.' => Re::Set(ByteSet::dot()),
            b'\\' => {
                let c = self.escape();
                Re::Set(ByteSet::single(c, self.case_insensitive))
            }
            b'{' => {
                let start = self.i;
                while self.peek() != Some(b'}') {
                    self.i += 1;
                }
                let name = std::str::from_utf8(&self.s[start..self.i]).unwrap_or_default();
                self.i += 1;
                let def = self.defs.get(name).unwrap_or_else(|| panic!("unknown flex definition {}", name));
                // flex expands a definition as if it were in parentheses.
                ReParser::parse(def, self.case_insensitive, self.defs)
            }
            _ => Re::Set(ByteSet::single(c, self.case_insensitive)),
        }
    }

    fn class_char(&mut self) -> u8 {
        let c = self.next();
        if c == b'\\' { self.escape() } else { c }
    }

    fn parse_class(&mut self) -> Re {
        let mut set = ByteSet::default();
        let negate = if self.peek() == Some(b'^') {
            self.i += 1;
            true
        } else {
            false
        };
        let mut first = true;
        loop {
            if self.peek() == Some(b']') && !first {
                self.i += 1;
                break;
            }
            first = false;
            let lo = self.class_char();
            if self.peek() == Some(b'-') && self.s.get(self.i + 1).is_some_and(|&c| c != b']') {
                self.i += 1;
                let hi = self.class_char();
                for b in lo..=hi {
                    set.insert(b);
                }
            } else {
                set.insert(lo);
            }
        }
        if self.case_insensitive {
            set.add_other_cases();
        }
        if negate {
            set.negate();
        }
        Re::Set(set)
    }
}

/// NFA node.
#[derive(Debug, Clone, Copy)]
enum NState {
    /// Consumes one byte of the set and goes to the next node.
    Set(ByteSet, u32),
    /// Epsilon transitions to both nodes.
    Split(u32, u32),
    /// The rule with this index matched.
    Accept(u32),
}

const DFA_UNKNOWN: u32 = u32::MAX;
const DFA_DEAD: u32 = u32::MAX - 1;
const NO_ACCEPT: u32 = u32::MAX;

/// A state of the lazily built DFA: a set of NFA nodes.
struct DState {
    nfa: Box<[u32]>,
    /// Lowest rule index accepted in this state.
    accept: u32,
    next: Box<[u32; 256]>,
}

/// The compiled scanner: every rule compiled into one NFA, plus the cache of
/// DFA states.
struct Automaton {
    nfa: Vec<NState>,
    /// Entry node of each rule (the default rule is the last one).
    rule_starts: Vec<u32>,
    /// DFA start state of each start condition (built on demand).
    sc_starts: [u32; NUM_SC],
    states: Vec<DState>,
    index: HashMap<Box<[u32]>, u32>,
    /// Scratch space for the epsilon closures.
    mark: Vec<u32>,
    generation: u32,
}

impl Automaton {
    fn build() -> Self {
        let defs: HashMap<&'static str, &'static str> = DEFS.iter().copied().collect();
        let mut a = Automaton {
            nfa: Vec::new(),
            rule_starts: Vec::new(),
            sc_starts: [DFA_UNKNOWN; NUM_SC],
            states: Vec::new(),
            index: HashMap::new(),
            mark: Vec::new(),
            generation: 0,
        };
        for (i, rule) in RULES.iter().enumerate() {
            let re = ReParser::parse(rule.pat, false, &defs);
            let accept = a.push(NState::Accept(i as u32));
            let start = a.compile(&re, accept);
            a.rule_starts.push(start);
        }
        // flex's default rule: `.|\n  ECHO;`
        let mut any = ByteSet::default();
        any.negate();
        let accept = a.push(NState::Accept(RULES.len() as u32));
        let start = a.push(NState::Set(any, accept));
        a.rule_starts.push(start);
        a.mark = vec![0; a.nfa.len()];
        a
    }

    fn push(&mut self, s: NState) -> u32 {
        self.nfa.push(s);
        (self.nfa.len() - 1) as u32
    }

    /// Thompson construction: returns the entry node of `re`, whose exit
    /// continues to `next`.
    fn compile(&mut self, re: &Re, next: u32) -> u32 {
        match re {
            Re::Set(s) => self.push(NState::Set(*s, next)),
            Re::Cat(items) => {
                let mut n = next;
                for r in items.iter().rev() {
                    n = self.compile(r, n);
                }
                n
            }
            Re::Alt(alts) => {
                let starts: Vec<u32> = alts.iter().map(|r| self.compile(r, next)).collect();
                let mut it = starts.into_iter().rev();
                let mut n = it.next().unwrap_or(next);
                for s in it {
                    n = self.push(NState::Split(s, n));
                }
                n
            }
            Re::Star(r) => {
                let id = self.push(NState::Split(0, 0));
                let body = self.compile(r, id);
                self.nfa[id as usize] = NState::Split(body, next);
                id
            }
            Re::Plus(r) => {
                let id = self.push(NState::Split(0, 0));
                let body = self.compile(r, id);
                self.nfa[id as usize] = NState::Split(body, next);
                body
            }
            Re::Opt(r) => {
                let body = self.compile(r, next);
                self.push(NState::Split(body, next))
            }
            Re::Repeat(r, min, max) => {
                let mut items: Vec<Re> = (0..*min).map(|_| (**r).clone()).collect();
                match max {
                    None => items.push(Re::Star(r.clone())),
                    Some(max) => {
                        for _ in *min..*max {
                            items.push(Re::Opt(r.clone()));
                        }
                    }
                }
                self.compile(&Re::Cat(items), next)
            }
        }
    }

    /// Epsilon closure of `seeds`, as a DFA state id.
    fn state_for(&mut self, seeds: &[u32]) -> u32 {
        self.generation = self.generation.wrapping_add(1);
        if self.generation == 0 {
            self.mark.iter_mut().for_each(|m| *m = 0);
            self.generation = 1;
        }
        let generation = self.generation;
        let mut stack: Vec<u32> = seeds.to_vec();
        let mut set: Vec<u32> = Vec::new();
        let mut accept = NO_ACCEPT;
        while let Some(n) = stack.pop() {
            if self.mark[n as usize] == generation {
                continue;
            }
            self.mark[n as usize] = generation;
            match self.nfa[n as usize] {
                NState::Set(..) => set.push(n),
                NState::Split(a, b) => {
                    stack.push(b);
                    stack.push(a);
                }
                NState::Accept(r) => {
                    accept = accept.min(r);
                    set.push(n);
                }
            }
        }
        if set.is_empty() {
            return DFA_DEAD;
        }
        set.sort_unstable();
        let key: Box<[u32]> = set.into_boxed_slice();
        if let Some(&id) = self.index.get(&key) {
            return id;
        }
        let id = self.states.len() as u32;
        self.states.push(DState { nfa: key.clone(), accept, next: Box::new([DFA_UNKNOWN; 256]) });
        self.index.insert(key, id);
        id
    }

    fn start(&mut self, sc: Sc) -> u32 {
        let s = self.sc_starts[sc as usize];
        if s != DFA_UNKNOWN {
            return s;
        }
        let mut seeds: Vec<u32> =
            RULES.iter().enumerate().filter(|(_, r)| r.scs.contains(&sc)).map(|(i, _)| self.rule_starts[i]).collect();
        seeds.push(self.rule_starts[RULES.len()]);
        // Keep the seeds in rule order so that `accept` (the lowest rule
        // index) is what flex would pick.
        let s = self.state_for(&seeds);
        self.sc_starts[sc as usize] = s;
        s
    }

    fn step(&mut self, state: u32, b: u8) -> u32 {
        let n = self.states[state as usize].next[b as usize];
        if n != DFA_UNKNOWN {
            return n;
        }
        let seeds: Vec<u32> = self.states[state as usize]
            .nfa
            .iter()
            .filter_map(|&n| match self.nfa[n as usize] {
                NState::Set(set, next) if set.contains(b) => Some(next),
                _ => None,
            })
            .collect();
        let n = if seeds.is_empty() { DFA_DEAD } else { self.state_for(&seeds) };
        self.states[state as usize].next[b as usize] = n;
        n
    }

    /// Longest match of the rules of `sc` at the start of `input`:
    /// `(length, rule index)`. `input` must not be empty (the default rule
    /// then always matches).
    fn longest_match(&mut self, sc: Sc, input: &[u8]) -> (usize, usize) {
        let mut state = self.start(sc);
        let mut best = (0usize, self.states[state as usize].accept);
        for (i, &b) in input.iter().enumerate() {
            state = self.step(state, b);
            if state == DFA_DEAD {
                break;
            }
            let acc = self.states[state as usize].accept;
            if acc != NO_ACCEPT {
                best = (i + 1, acc);
            }
        }
        (best.0, best.1 as usize)
    }
}

/// The automaton is shared by every scanner of the process (it only grows
/// its cache of DFA states).
fn automaton() -> &'static Mutex<Automaton> {
    static A: OnceLock<Mutex<Automaton>> = OnceLock::new();
    A.get_or_init(|| Mutex::new(Automaton::build()))
}

// ---------------------------------------------------------------------------
// The scanner
// ---------------------------------------------------------------------------

/// A flex input buffer (`YY_BUFFER_STATE`).
struct Buffer {
    data: Vec<u8>,
    pos: usize,
}

/// `yy_scan_string`: flex copies the string up to its NUL terminator.
fn c_str(data: &[u8]) -> Vec<u8> {
    match data.iter().position(|&c| c == 0) {
        Some(p) => data[..p].to_vec(),
        None => data.to_vec(),
    }
}

/// `find_separator`: the text after the first space or tab.
fn find_separator(s: &[u8]) -> &[u8] {
    match s.iter().position(|&c| c == b' ' || c == b'\t') {
        Some(p) => &s[p + 1..],
        None => &s[s.len()..],
    }
}

/// `strchr(s, ' ') + 2`
fn after_space_plus_one(s: &[u8]) -> &[u8] {
    // C++ dereferences a null pointer when there is no space (the
    // separator was a tab); an empty value is returned instead.
    match s.iter().position(|&c| c == b' ') {
        Some(p) => &s[(p + 2).min(s.len())..],
        None => &[],
    }
}

fn sanitize(s: &[u8]) -> Vec<u8> {
    parser_sanitizer(String::from_utf8_lossy(s).into_owned()).into_bytes()
}

/// The scanner state (flex's global state in C++).
pub(crate) struct Scanner {
    buffers: Vec<Buffer>,
    start: Sc,
    /// `YY_PREVIOUS_STATE`
    previous_states: Vec<Sc>,
    /// `state_variable_from`: set by `SecRuleUpdateTarget*` so that the
    /// variables are not followed by an operator.
    ///
    /// C++ keeps this flag and `YY_PREVIOUS_STATE` in static variables that
    /// survive from one parse to the next; here they belong to the scanner
    /// of one parse (they are always reset by a successful scan anyway).
    state_variable_from: i32,
}

impl Scanner {
    /// `Driver::scan_begin`: scans `buffer` (up to its first NUL byte, as
    /// `yy_scan_string` does).
    pub(crate) fn new(buffer: &[u8]) -> Self {
        Scanner {
            buffers: vec![Buffer { data: c_str(buffer), pos: 0 }],
            start: Sc::Initial,
            previous_states: Vec::new(),
            state_variable_from: 0,
        }
    }

    fn begin_previous(&mut self) {
        // std::stack::top on an empty stack is undefined behaviour in C++.
        self.start = self.previous_states.pop().unwrap_or(Sc::Initial);
    }

    /// `yylex`
    pub(crate) fn lex(&mut self, driver: &mut Driver) -> Result<Token, ScanError> {
        // Code run each time yylex is called.
        driver.loc_back_mut().step();
        loop {
            let Some(buf) = self.buffers.last() else {
                return Ok(Token { kind: sym::END, value: Vec::new(), loc: *driver.loc_back() });
            };
            if buf.pos >= buf.data.len() {
                if self.start == Sc::FinishActions {
                    // <FINISH_ACTIONS><<EOF>> { BEGIN(INITIAL); yyless(0); p::make_NEW_LINE(...); }
                    self.start = Sc::Initial;
                    continue;
                }
                // <<EOF>>
                self.buffers.pop();
                if self.buffers.is_empty() {
                    return Ok(Token { kind: sym::END, value: Vec::new(), loc: *driver.loc_back() });
                }
                driver.loc.pop();
                continue;
            }
            let text_start = buf.pos;
            let (len, rule) = {
                let mut a = automaton().lock().unwrap_or_else(|e| e.into_inner());
                a.longest_match(self.start, &buf.data[buf.pos..])
            };
            let mut yyleng = len;
            let top = self.buffers.len() - 1;
            self.buffers[top].pos += len;
            // YY_USER_ACTION
            driver.loc_back_mut().columns(len as i32);
            if rule == RULES.len() {
                // ECHO
                let mut out = std::io::stdout().lock();
                let _ = out.write_all(&self.buffers[top].data[text_start..text_start + len]);
                continue;
            }
            for op in RULES[rule].ops {
                match *op {
                    Op::Ret(kind, v) => {
                        let text = &self.buffers[top].data[text_start..text_start + yyleng];
                        let value = match v {
                            V::None => Vec::new(),
                            V::Text => text.to_vec(),
                            V::FindSep => find_separator(text).to_vec(),
                            V::SanFindSep => sanitize(find_separator(text)),
                            V::Strchr2 => after_space_plus_one(text).to_vec(),
                            V::SanStrchr2 => sanitize(after_space_plus_one(text)),
                            V::Sub(pos, shrink) => {
                                let end = (pos + yyleng.saturating_sub(shrink)).min(text.len());
                                text[pos.min(end)..end].to_vec()
                            }
                        };
                        return Ok(Token { kind, value, loc: *driver.loc_back() });
                    }
                    Op::Begin(sc) => self.start = sc,
                    Op::BeginX(sc) => {
                        self.previous_states.push(self.start);
                        self.start = sc;
                    }
                    Op::BeginXVarParameter => {
                        self.previous_states.push(self.start);
                        self.start = match self.start {
                            Sc::SetvarActionNonquoted => Sc::ExpectingVarParameterOrMacroNonquoted,
                            Sc::SetvarActionQuoted => Sc::ExpectingVarParameterOrMacroQuoted,
                            _ => Sc::ExpectingVarParameter,
                        };
                    }
                    Op::BeginPrevious => self.begin_previous(),
                    Op::BeginParameter => {
                        self.start = if self.start == Sc::ExpectingOperatorEndsWithSpace {
                            Sc::TransitionFromOpToExpectingParameterEndsWithSpace
                        } else {
                            Sc::TransitionFromOpToExpectingParameterEndsWithQuote
                        };
                    }
                    Op::BeginNoOpInformed => {
                        self.start = if self.start == Sc::ExpectingOperatorEndsWithSpace {
                            Sc::NoOpInformedEndsWithSpace
                        } else {
                            Sc::NoOpInformedEndsWithQuote
                        };
                    }
                    Op::BeginActionOperation => {
                        self.start = match self.start {
                            Sc::SetvarActionNonquoted => Sc::SetvarActionNonquotedWaitingOperation,
                            Sc::SetvarActionQuoted => Sc::SetvarActionQuotedWaitingOperation,
                            s => s,
                        };
                    }
                    Op::BeginActionWaitingContent => {
                        self.start = match self.start {
                            Sc::SetvarActionNonquotedWaitingOperation => Sc::SetvarActionNonquotedWaitingContent,
                            Sc::SetvarActionQuotedWaitingOperation => Sc::SetvarActionQuotedWaitingContent,
                            Sc::ExpectingVarParameterOrMacroQuoted => Sc::SetvarActionQuotedWaitingContent,
                            Sc::ExpectingVarParameterOrMacroNonquoted => Sc::SetvarActionNonquotedWaitingContent,
                            s => s,
                        };
                    }
                    Op::Less(l) => {
                        let n = match l {
                            L::Abs(n) => n,
                            L::LenMinus(n) => yyleng - n,
                        };
                        yyleng = n;
                        self.buffers[top].pos = text_start + n;
                    }
                    Op::Lines => driver.loc_back_mut().lines(1),
                    Op::Step => driver.loc_back_mut().step(),
                    Op::SetStateVariableFrom => self.state_variable_from = 1,
                    Op::IfStateVariableFrom(sc) => {
                        if self.state_variable_from == 0 {
                            self.start = sc;
                        } else {
                            self.state_variable_from = 0;
                            self.start = Sc::Initial;
                        }
                    }
                    Op::Error(msg, with_text) => {
                        let text = if with_text {
                            String::from_utf8_lossy(&self.buffers[top].data[text_start..text_start + yyleng])
                                .into_owned()
                        } else {
                            String::new()
                        };
                        let loc = *driver.loc_back();
                        driver.error(&loc, msg, &text);
                        return Err(ScanError { loc });
                    }
                    Op::Include(quoted) => {
                        let text = String::from_utf8_lossy(&self.buffers[top].data[text_start..text_start + yyleng])
                            .into_owned();
                        self.include(driver, &text, quoted)?;
                    }
                    Op::RemoteRules => {
                        let buf = &self.buffers[top];
                        let text = String::from_utf8_lossy(&buf.data[text_start..text_start + yyleng]).into_owned();
                        // Pushing the buffer state makes flex's `yytext` point
                        // at the input that follows the directive (up to the
                        // end of the buffer): that is what the C++ error
                        // message shows.
                        let rest = &buf.data[buf.pos..];
                        let rest = &rest[..rest.iter().position(|&c| c == 0).unwrap_or(rest.len())];
                        let rest = String::from_utf8_lossy(rest).into_owned();
                        self.remote_rules(driver, &text, &rest)?;
                    }
                }
            }
        }
    }

    /// `{CONFIG_INCLUDE}[ \t]+{CONFIG_VALUE_PATH}` and its quoted variant:
    /// pushes one buffer per file matched by the (glob) expansion of the
    /// path, the first file on top.
    fn include(&mut self, driver: &mut Driver, yytext: &str, quoted: bool) -> Result<(), ScanError> {
        // `yytext + strlen("include")`
        let tmp = yytext.get("include".len()..).unwrap_or("");
        let after_whitespace = tmp.trim_start_matches([' ', '\t']);
        let file = if quoted {
            after_whitespace.get(1..after_whitespace.len().saturating_sub(1)).unwrap_or("")
        } else {
            after_whitespace
        };
        let current = driver.filename(driver.loc_back().end.filename).to_string();
        let lookup = find_resource(file, &current);
        let Some(fi) = lookup.path else {
            self.start = Sc::Initial;
            let loc = *driver.loc_back();
            driver.error(&loc, "", &format!("{}: Not able to open file. {}", file, lookup.looked_at));
            return Err(ScanError { loc });
        };
        let mut files = expand_env(&fi, 0);
        files.reverse();
        for s in files {
            let current = driver.filename(driver.loc_back().end.filename).to_string();
            let lookup = find_resource(&s, &current);
            let f = lookup.path.unwrap_or_default();
            let idx = driver.add_filename(f.clone());
            driver.loc.push(Location::new(idx));
            match std::fs::read(&f) {
                Ok(data) => self.buffers.push(Buffer { data, pos: 0 }),
                Err(_) => {
                    self.start = Sc::Initial;
                    driver.loc.pop();
                    let loc = *driver.loc_back();
                    driver.error(&loc, "", &format!("{}: Not able to open file. {}", s, lookup.looked_at));
                    return Err(ScanError { loc });
                }
            }
        }
        Ok(())
    }

    /// `{CONFIG_SEC_REMOTE_RULES}[ ][^ ]+[ ][^\n\r ]+`: downloads the rules
    /// and scans them as a new buffer.
    fn remote_rules(&mut self, driver: &mut Driver, yytext: &str, yytext_after_push: &str) -> Result<(), ScanError> {
        let mut c = HttpsClient::new();
        let conf = split(yytext.as_bytes(), b' ');
        if conf.len() < 3 {
            // C++ only checks for fewer than two fields (and then reads the
            // third one); the pattern always yields three.
            let loc = *driver.loc_back();
            driver.error(&loc, "", "SecRemoteRules demands a key and a URI");
            return Err(ScanError { loc });
        }
        let key = String::from_utf8_lossy(&conf[1]).into_owned();
        let url = String::from_utf8_lossy(&conf[2]).into_owned();
        c.set_key(&key);

        let idx = driver.add_filename(url.clone());
        driver.loc.push(Location::new(idx));

        let ret = c.download(&url);
        if !ret {
            self.start = Sc::Initial;
            match driver.properties.remote_rules_action_on_failed {
                Some(OnFailedRemoteRulesAction::Warn) => {
                    // TODO (C++): Implement the server logging mechanism.
                }
                Some(OnFailedRemoteRulesAction::Abort) => {
                    let loc = *driver.loc_back();
                    driver.error(&loc, "", &format!("{} - Failed to download: {}", yytext_after_push, c.error));
                    return Err(ScanError { loc });
                }
                _ => {}
            }
        }
        self.buffers.push(Buffer { data: c_str(&c.content), pos: 0 });
        Ok(())
    }
}

