#[cfg(test)]
mod tests {
    use super::*;

    fn matches(pattern: &str, input: &str) -> Option<usize> {
        let defs: HashMap<&'static str, &'static str> = DEFS.iter().copied().collect();
        let re = ReParser::parse(pattern, false, &defs);
        // Simulate the NFA directly (longest match from the start).
        let mut a = Automaton {
            nfa: Vec::new(),
            rule_starts: Vec::new(),
            sc_starts: [DFA_UNKNOWN; NUM_SC],
            states: Vec::new(),
            index: HashMap::new(),
            mark: Vec::new(),
            generation: 0,
        };
        let accept = a.push(NState::Accept(0));
        let start = a.compile(&re, accept);
        a.mark = vec![0; a.nfa.len()];
        let mut state = a.state_for(&[start]);
        let mut best = if state != DFA_DEAD && a.states[state as usize].accept == 0 { Some(0) } else { None };
        for (i, &b) in input.as_bytes().iter().enumerate() {
            if state == DFA_DEAD {
                break;
            }
            state = a.step(state, b);
            if state != DFA_DEAD && a.states[state as usize].accept == 0 {
                best = Some(i + 1);
            }
        }
        best
    }

    #[test]
    fn flex_patterns() {
        assert_eq!(matches("(?i:SecRule)", "secrule ARGS"), Some(7));
        assert_eq!(matches("{CONFIG_VALUE_PATH}", "/Foo/BAR.conf\n"), Some(13));
        assert_eq!(matches("[^\\\\n]", "n"), None);
        assert_eq!(matches("[^\\\\n]", "\\"), None);
        assert_eq!(matches("[^\\\\n]", "x"), Some(1));
        assert_eq!(matches("[ \\t]*", "x"), Some(0));
        assert_eq!(matches(".+", "abc\ndef"), Some(3));
        assert_eq!(matches("[+|-]{AUDIT_PARTS}", "+ABZ,"), Some(4));
        assert_eq!(matches("{ACTION_ID}", "ID:'123'"), Some(8));
        assert_eq!(matches("{FREE_TEXT_DOUBLE_QUOTE_MACRO_EXPANSION}", "a\\\"b\" x"), Some(4));
        assert_eq!(matches("a{2,3}", "aaaa"), Some(3));
        assert_eq!(matches("\"ab\"c", "abc"), Some(3));
    }

    #[test]
    fn helpers() {
        assert_eq!(find_separator(b"SecDebugLogLevel   9"), b"  9");
        assert_eq!(find_separator(b"abc"), b"");
        assert_eq!(after_space_plus_one(b"SecComponentSignature \"x\""), b"x\"");
        assert_eq!(c_str(b"ab\0cd"), b"ab");
    }

    fn tokens(input: &str) -> Vec<(u16, String)> {
        let mut d = Driver::new();
        let idx = d.add_filename("t".to_string());
        d.loc.push(Location::new(idx));
        let mut s = Scanner::new(input.as_bytes());
        let mut out = Vec::new();
        loop {
            let t = s.lex(&mut d).expect("no scanner error");
            if t.kind == sym::END {
                break;
            }
            out.push((t.kind, String::from_utf8_lossy(&t.value).into_owned()));
        }
        out
    }

    #[test]
    fn rule_tokens() {
        let t = tokens("SecRule ARGS:foo|!ARGS:bar \"@rx ^a%{tx.b}\" \"id:1,msg:'x y',setvar:tx.a=+1\"\n");
        let kinds: Vec<u16> = t.iter().map(|(k, _)| *k).collect();
        assert_eq!(
            kinds,
            vec![
                sym::DIRECTIVE,
                sym::VARIABLE_ARGS,
                sym::DICT_ELEMENT,
                sym::PIPE,
                sym::VAR_EXCLUSION,
                sym::VARIABLE_ARGS,
                sym::DICT_ELEMENT,
                sym::OPERATOR_RX,
                sym::FREE_TEXT_QUOTE_MACRO_EXPANSION,
                sym::VARIABLE_TX,
                sym::DICT_ELEMENT,
                sym::ACTION_ID,
                sym::COMMA,
                sym::ACTION_MSG,
                sym::FREE_TEXT_QUOTE_MACRO_EXPANSION,
                sym::COMMA,
                sym::ACTION_SETVAR,
                sym::VARIABLE_TX,
                sym::FREE_TEXT_QUOTE_MACRO_EXPANSION,
                sym::SETVAR_OPERATION_EQUALS_PLUS,
                sym::FREE_TEXT_QUOTE_MACRO_EXPANSION,
            ]
        );
        assert_eq!(t[2].1, "foo");
        assert_eq!(t[8].1, "^a");
        assert_eq!(t[14].1, "x y");
    }

    #[test]
    fn continuation_lines() {
        let mut d = Driver::new();
        let idx = d.add_filename("t".to_string());
        d.loc.push(Location::new(idx));
        let mut s = Scanner::new(b"SecAction \\\n  \"id:1,\\\n pass\"\nSecRuleEngine On");
        let mut last = Location::new(idx);
        loop {
            let t = s.lex(&mut d).expect("no scanner error");
            if t.kind == sym::END {
                break;
            }
            last = t.loc;
        }
        // The continuation line right after `SecAction` is not counted: the
        // TRANSACTION_FROM_DIRECTIVE_TO_ACTIONS rules do not call
        // `lines(1)` (same as the C++ scanner).
        assert_eq!((last.end.line, last.end.column), (3, 17));
    }
}
